'use strict';
let dailyQuestions=null,dailyAnswers=[],dailyPosition=0,dailyEdition='',dailyAttemptId='',dailyGoalTarget=10000,dailyTimer=null,dailyTimerAnchor=0,dailyBusy=false,dailyRequestEpoch=0,dailyAbort=null,dailyDialog=null;
const DAILY_CHECKPOINT_KEY='english-quest-daily-checkpoint-v1';

function boardTime(value){const at=Number(value);if(!Number.isFinite(at)||at<=0)return '时间未记录';const date=new Date(at);if(!Number.isFinite(date.getTime()))return '时间未记录';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(date).replaceAll('/','-');}
function boardEntryRow(entry,index){const at=Number(entry.submittedAt),date=new Date(at),valid=Number.isFinite(at)&&at>0&&Number.isFinite(date.getTime()),time=boardTime(at),rank=Number.isSafeInteger(entry.rank)&&entry.rank>0?entry.rank:index+1;return `<div class="daily-row"><b aria-label="总榜第 ${rank} 名">${rank}</b><span style="min-width:0;overflow-wrap:anywhere">${esc(entry.name)}${entry.username?`<small style="display:block;font-size:12px;overflow-wrap:anywhere">@${esc(entry.username)}</small>`:''}<small style="display:block;font-size:12px;line-height:1.5;overflow-wrap:anywhere">上榜 ${valid?`<time datetime="${esc(date.toISOString())}">${esc(time)}</time>`:esc(time)}</small></span><strong>${esc(entry.correct)}/20</strong><small>${Math.ceil(entry.timeMs/1000)} 秒</small></div>`;}
function legacyBoard(entries){if(!entries?.length)return '';return `<details class="panel" style="margin-top:20px"><summary>旧题库历史成绩 · ${entries.length} 条</summary><p class="caption">旧记录没有完整题库版本或精确上榜时刻，仅供回看，不与新版永久榜比较。</p><div class="daily-list">${entries.map((entry,index)=>`<div class="daily-row"><b>${index+1}</b><span>${esc(entry.name)}<small style="display:block;line-height:1.5">记录日期 ${esc(entry.legacyDate||'未记录')}</small></span><strong>${esc(entry.correct)}/20</strong><small>${Math.ceil(entry.timeMs/1000)} 秒</small></div>`).join('')}</div></details>`;}
function boardSubmitMessage(result,label='榜单挑战'){return `${label}答对 ${result.correct}/20，用时 ${Math.ceil(result.timeMs/1000)} 秒。${result.improved===false?'保留了更好的原成绩。':result.improved===true?'本次最佳成绩已上榜。':'成绩已提交。'}`;}
const BOARD_PAGE_SIZE=50,boardViews=new Map();
function createBoardView(scope,id,title){const previous=boardViews.get(scope),state={scope,id,title,query:previous?.id===id?previous.query:'',page:0,entries:[],legacyEntries:[],total:0,matched:0,limit:1000,loading:true,error:false,request:0};boardViews.set(scope,state);return state;}
function boardViewActive(state){const path=location.hash.slice(1).split('?')[0];return boardViews.get(state.scope)===state&&(state.scope==='main'?path==='daily'&&C.goal(p)===state.id:path==='industries'&&industryData().id===state.id);}
function renderBoardView(state){if(!boardViewActive(state))return;const target=document.getElementById(state.scope==='main'?'daily-board':'industry-board');if(!target)return;const pages=Math.max(1,Math.ceil(state.entries.length/BOARD_PAGE_SIZE));state.page=Math.max(0,Math.min(state.page,pages-1));const start=state.page*BOARD_PAGE_SIZE,shown=state.entries.slice(start,start+BOARD_PAGE_SIZE),summary=state.query?`匹配 ${num(state.matched)} 人 · 展示 ${num(state.entries.length)} 人${state.matched>state.entries.length?'（最多 1,000 个搜索结果）':''} · 保留全榜原名次`:`共 ${num(state.total)} 人上榜 · 展示前 ${num(state.entries.length)} 名（最多 1,000 名）`;
 target.innerHTML=`<h3>${esc(state.title)}</h3><p class="caption">每人保留最好成绩，不按日期清榜；同题库版本比较，上榜时间为北京时间。</p><form id="${state.scope}-board-search-form" role="search" aria-label="搜索${esc(state.title)}" style="margin:16px 0;min-width:0"><label for="${state.scope}-board-query">按用户名或榜单昵称找人</label><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;min-width:0"><input id="${state.scope}-board-query" class="answer-field" type="search" maxlength="80" value="${esc(state.query)}" placeholder="输入名字的一部分，不区分大小写" autocomplete="off" style="flex:1 1 180px;min-width:0;max-width:100%;min-height:44px;margin:0"><button type="submit" class="secondary" style="min-height:44px">搜索</button>${button('清除','leaderboard-clear','ghost',`data-id="${state.scope}" style="min-height:44px"`)}</div></form><div role="status" aria-live="polite">${state.loading?'<p class="muted">正在查询排行榜…</p>':state.error?'<p class="muted">榜单暂时无法读取，可重新搜索；练习仍可继续。</p>':`<p class="caption">${summary}</p><div class="daily-list">${shown.length?shown.map((entry,index)=>boardEntryRow(entry,start+index)).join(''):state.query?'<div class="empty">没找到这位学习者。试试更短的名字，或清除搜索查看榜单。</div>':'<div class="empty">还没有人上榜，你可以第一个出发。</div>'}</div>${state.entries.length>BOARD_PAGE_SIZE?`<div class="button-row" style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px">${button('上一页','leaderboard-page','ghost',`data-id="${state.scope}:-1" style="min-height:44px" ${state.page===0?'disabled':''}`)}<span>第 ${state.page+1} / ${pages} 页 · 每页 50 人</span>${button('下一页','leaderboard-page','ghost',`data-id="${state.scope}:1" style="min-height:44px" ${state.page>=pages-1?'disabled':''}`)}</div>`:''}${legacyBoard(state.legacyEntries)}`}</div>`;
 document.getElementById(`${state.scope}-board-search-form`)?.addEventListener('submit',event=>{event.preventDefault();searchBoard(state.scope);});
}
async function loadBoardView(state,query=state.query){if(!boardViewActive(state))return;state.query=String(query).trim().slice(0,80);state.page=0;state.loading=true;state.error=false;const request=++state.request;renderBoardView(state);const url=state.scope==='main'?`/api/daily/leaderboard?goal=${state.id}`:`/api/industries/leaderboard?sector=${encodeURIComponent(state.id)}`;
 try{const response=await fetch(url+(state.query?'&q='+encodeURIComponent(state.query):''));if(!response.ok)throw Error();const data=await response.json();if(!boardViewActive(state)||request!==state.request)return;state.entries=data.entries;state.legacyEntries=data.legacyEntries||[];state.total=Number.isFinite(data.total)?data.total:data.entries.length;state.matched=Number.isFinite(data.matched)?data.matched:data.entries.length;state.limit=data.limit||1000;state.loading=false;renderBoardView(state);}catch{if(!boardViewActive(state)||request!==state.request)return;state.loading=false;state.error=true;renderBoardView(state);}
}
async function searchBoard(scope,clear=false){const state=boardViews.get(scope);if(!state)return;const query=clear?'':document.getElementById(`${scope}-board-query`)?.value||'';await loadBoardView(state,query);}
function pageBoard(value){const [scope,direction]=String(value).split(':'),state=boardViews.get(scope);if(!state||state.loading||![-1,1].includes(Number(direction)))return;state.page+=Number(direction);renderBoardView(state);}
Object.assign(actions,{'leaderboard-clear':scope=>searchBoard(scope,true),'leaderboard-page':value=>pageBoard(value)});
async function renderDaily(){const goal=C.goal(p),state=createBoardView('main',goal,'永久排行榜');
 app.innerHTML=intro(`${num(goal)} 词永久榜。`,'不按日期清榜；每人保留最好成绩；1,000至20,000词，每1,000词一档，各档独立排名。')+`<div class="goal-picker" role="group" aria-label="选择排行榜词量"><span>参赛词量</span><div class="goal-options">${goalButtons()}</div></div><div class="profile-grid"><section class="panel"><h2>20 题榜单挑战</h2><p class="muted">选出单词的中文意思。每次开始重新计时，可反复挑战；答对更多，或同分更快，才会替换原成绩。</p><p class="caption">每1,000词有两次免计时休息，额度用完后仍可计时休息。离页和关闭页面不会自动停表。</p>${dailyStoredCheckpoint()?button('继续未完成挑战','daily-resume','secondary')+button('放弃本轮，重来','daily-restart','ghost'):button('开始榜单挑战','daily-start')}</section><section class="panel" id="daily-board"></section></div><p class="caption">20 题挑战成绩与主线通关段位分开。完整路线段位仍按通关后答错过的不同词数结算；题库升级后各版本分开排名。默认展示前 1,000 名，搜索可查所有已上榜记录，包括 1,000 名以外的学习者。登录后使用同一账号记录；访客身份不能防止换设备重复参赛。</p>`;
 await loadBoardView(state);
}
function dailySetTimer(data){dailyTimer={...data};dailyTimerAnchor=Date.now();}
function dailyElapsed(){if(!dailyTimer)return 0;return dailyTimer.elapsedMs+(dailyTimer.paused&&dailyTimer.freePause?0:Math.max(0,Date.now()-dailyTimerAnchor));}
function dailyToolbar(){if(!dailyTimer)return '';const left=dailyTimer.restRemaining;return `<div class="run-toolbar" aria-label="榜单本轮计时"><span><b data-daily-run-clock>${runDuration(dailyElapsed())}</b><small>免费休息剩 ${left} / ${dailyTimer.restLimit} 次</small></span><div>${button('休息','daily-rest','secondary',`${left?'':'disabled'} ${dailyBusy?'disabled':''}`)}${!left?button('计时休息','daily-rest','ghost',dailyBusy?'disabled':''):''}${button('重来','daily-restart','ghost',dailyBusy?'disabled':'')}</div></div>`;}
function dailyStoredCheckpoint(){try{const item=JSON.parse(localStorage.getItem(DAILY_CHECKPOINT_KEY)||'null');if(!item||!C.validGoal(item.goal)||item.goal!==C.goal(p)||typeof item.edition!=='string'||typeof item.attemptId!=='string'||!item.attemptId||!Array.isArray(item.questions)||item.questions.length!==20||!Array.isArray(item.answers)||item.answers.length>20||!item.answers.every(x=>Number.isSafeInteger(x)&&x>=1&&x<=20000)||JSON.stringify(item).length>80000)return null;for(const q of item.questions){if(typeof q.word!=='string'||q.word.length>100||!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>!Number.isSafeInteger(o.id)||o.id<1||o.id>20000||typeof o.zh!=='string'||o.zh.length>500))return null;}return item;}catch{return null;}}
function dailyCheckpoint(){if(!dailyQuestions||!dailyAttemptId)return;try{localStorage.setItem(DAILY_CHECKPOINT_KEY,JSON.stringify({attemptId:dailyAttemptId,goal:dailyGoalTarget,edition:dailyEdition,questions:dailyQuestions,answers:dailyAnswers,name:document.getElementById('daily-name')?.value||''}));}catch{}}
function dailyClearCheckpoint(){try{localStorage.removeItem(DAILY_CHECKPOINT_KEY);}catch{}}
function dailyRoundInvalidate(){dailyRequestEpoch++;dailyAbort?.abort();dailyAbort=null;dailyQuestions=null;dailyAnswers=[];dailyAttemptId='';dailyEdition='';dailyPosition=0;dailyTimer=null;dailyBusy=false;if(dailyDialog?.open)dailyDialog.close();dailyClearCheckpoint();}
async function dailyAttemptAction(action){const epoch=dailyRequestEpoch,id=dailyAttemptId;const controller=new AbortController();dailyAbort=controller;const timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('/api/daily/attempt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({attemptId:id,goal:dailyGoalTarget,edition:dailyEdition,action}),signal:controller.signal});if(epoch!==dailyRequestEpoch||id!==dailyAttemptId)return null;if(!response.ok){const error=new Error((await response.text()).slice(0,100));error.status=response.status;throw error;}const data=await response.json();if(epoch!==dailyRequestEpoch||id!==dailyAttemptId)return null;if(!Number.isFinite(data.elapsedMs)||!Number.isInteger(data.restRemaining))throw Error('计时状态无法读取');dailySetTimer(data);dailyCheckpoint();return data;}finally{clearTimeout(timeout);if(dailyAbort===controller)dailyAbort=null;}}
async function dailyStart(){if(dailyBusy)return;const epoch=++dailyRequestEpoch;dailyBusy=true;const goal=C.goal(p);const controller=new AbortController();dailyAbort=controller;const timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(`/api/daily?goal=${goal}`,{signal:controller.signal});if(!r.ok)throw Error();const data=await r.json();if(epoch!==dailyRequestEpoch||location.hash.slice(1).split('?')[0]!=='daily'||C.goal(p)!==goal)return;dailyQuestions=data.questions;dailyEdition=data.edition||'';dailyAttemptId=data.attemptId||'';dailyGoalTarget=data.goal;dailyAnswers=[];dailyPosition=0;dailySetTimer(data);dailyCheckpoint();dailyBusy=false;renderDailyQuestion();}catch{if(epoch===dailyRequestEpoch)toast('榜单挑战暂时无法开始，请重试。');}finally{clearTimeout(timeout);if(epoch===dailyRequestEpoch)dailyBusy=false;if(dailyAbort===controller)dailyAbort=null;}}
async function dailyResume(){if(dailyBusy)return;const item=dailyStoredCheckpoint();if(!item){toast('没有可继续的本轮，请重新开始。');return;}dailyRequestEpoch++;dailyQuestions=item.questions;dailyAnswers=item.answers;dailyPosition=item.answers.length;dailyGoalTarget=item.goal;dailyEdition=item.edition;dailyAttemptId=item.attemptId;dailyBusy=true;const epoch=dailyRequestEpoch;try{const data=await dailyAttemptAction('status');if(!data||location.hash.slice(1).split('?')[0]!=='daily')return;dailyBusy=false;renderDailyQuestion();const name=document.getElementById('daily-name');if(name)name.value=String(item.name||'').slice(0,16);dailyCheckpoint();if(data.paused)dailyShowRest();}catch(error){if(epoch!==dailyRequestEpoch)return;if([400,403,409].includes(error.status)){dailyClearCheckpoint();dailyQuestions=null;}toast(error.message||'暂时无法恢复本轮，稍后再试。');}finally{if(epoch===dailyRequestEpoch)dailyBusy=false;}}
function renderDailyQuestion(){if(!dailyQuestions)return;if(dailyPosition>=dailyQuestions.length){app.innerHTML=`<section class="panel exercise-card question-card"><div class="eyebrow">${num(dailyGoalTarget)} 词 · 榜单挑战</div>${dailyToolbar()}<h2>20 题完成，提交成绩</h2><p class="muted">可多次挑战，只保留最好成绩。昵称和最佳成绩取得时刻会显示在公开排行榜。</p><input id="daily-name" class="answer-field" maxlength="16" placeholder="你的榜单昵称" aria-label="榜单昵称">${button('提交榜单成绩','daily-submit','primary daily-answer')}</section>`;return;}const q=dailyQuestions[dailyPosition];app.innerHTML=`<div class="exercise question-workspace"><div class="exercise-top"><span>榜单挑战 ${dailyPosition+1} / 20</span><div class="bar"><i style="width:${dailyPosition*5}%"></i></div></div>${dailyToolbar()}<section class="panel exercise-card question-card"><div class="eyebrow">英 → 中 · 选出意思</div><h2 class="question-title large">${esc(q.word)}</h2><div class="options">${q.options.map((x,i)=>button(`${i+1}. ${esc(x.zh)}`,'daily-answer','option',`data-id="${x.id}"`)).join('')}</div></section></div>`;}
function dailyAnswer(id){if(dailyBusy||dailyTimer?.paused||!dailyQuestions||dailyAnswers.length!==dailyPosition||!dailyQuestions[dailyPosition]?.options.some(o=>o.id===Number(id)))return;dailyAnswers.push(Number(id));dailyPosition++;dailyCheckpoint();renderDailyQuestion();}
function dailyGetDialog(){if(dailyDialog)return dailyDialog;dailyDialog=document.createElement('dialog');dailyDialog.className='run-dialog';dailyDialog.id='daily-run-dialog';dailyDialog.setAttribute('aria-labelledby','daily-run-title');document.body.append(dailyDialog);dailyDialog.addEventListener('cancel',event=>{event.preventDefault();if(!dailyTimer?.paused)dailyDialog.close();});return dailyDialog;}
function dailyShowRest(){const d=dailyGetDialog();d.innerHTML=`<div class="run-rest-icon" aria-hidden="true">☕</div><h2 id="daily-run-title">${dailyTimer.freePause?'休息中，计时已暂停':'休息中，计时继续'}</h2><p>${dailyTimer.freePause?'这段休息不计入榜单用时。':'免费额度已用完，这段休息计入榜单总用时。'}</p><strong class="run-rest-clock" data-daily-run-clock>${runDuration(dailyElapsed())}</strong><p>免费休息剩 ${dailyTimer.restRemaining} / ${dailyTimer.restLimit} 次。继续后回到原题。</p>${button('继续挑战','daily-rest-continue','primary')}`;if(!d.open)d.showModal();}
async function dailyPause(){if(dailyBusy||!dailyQuestions)return;dailyBusy=true;const epoch=dailyRequestEpoch;dailyCheckpoint();try{const data=await dailyAttemptAction('pause');if(data&&location.hash.slice(1).split('?')[0]==='daily')dailyShowRest();}catch{if(epoch!==dailyRequestEpoch)return;toast('休息状态尚未确认，请稍后重试。');try{await dailyAttemptAction('status');if(epoch===dailyRequestEpoch&&dailyTimer?.paused&&location.hash.slice(1).split('?')[0]==='daily')dailyShowRest();}catch{}}finally{if(epoch===dailyRequestEpoch)dailyBusy=false;}}
async function dailyContinue(){if(dailyBusy)return;const name=document.getElementById('daily-name')?.value||'';dailyBusy=true;const epoch=dailyRequestEpoch;try{const data=await dailyAttemptAction('resume');if(!data||epoch!==dailyRequestEpoch)return;if(dailyDialog?.open)dailyDialog.close();dailyBusy=false;if(location.hash.slice(1).split('?')[0]!=='daily')return;renderDailyQuestion();const field=document.getElementById('daily-name');if(field)field.value=name;dailyCheckpoint();}catch{if(epoch!==dailyRequestEpoch)return;toast('尚未恢复计时，请重试继续按钮。');}finally{if(epoch===dailyRequestEpoch)dailyBusy=false;}}
function dailyRestartAsk(){if(dailyBusy)return;const d=dailyGetDialog();d.innerHTML=`<h2 id="daily-run-title">放弃本轮，重新冲榜？</h2><p>本轮已答题和计时将放弃，新挑战从第1题开始，免费休息额度重新计算。已取得的最好榜单成绩保留。</p><div class="button-row">${button('放弃本轮，重来','daily-restart-confirm','primary')}${button('继续当前挑战','daily-restart-cancel','ghost')}</div>`;if(!d.open)d.showModal();}
async function dailyRestartConfirm(){if(dailyBusy)return;dailyBusy=true;const epoch=dailyRequestEpoch;const item=dailyQuestions?null:dailyStoredCheckpoint();if(item){dailyAttemptId=item.attemptId;dailyGoalTarget=item.goal;dailyEdition=item.edition;}try{if(dailyAttemptId){const data=await dailyAttemptAction('abandon');if(!data||epoch!==dailyRequestEpoch)return;}dailyClearCheckpoint();dailyQuestions=null;dailyTimer=null;dailyAnswers=[];if(dailyDialog?.open)dailyDialog.close();dailyBusy=false;await dailyStart();}catch(error){if(epoch!==dailyRequestEpoch)return;if([400,409].includes(error.status)){dailyClearCheckpoint();dailyQuestions=null;dailyTimer=null;dailyAttemptId='';if(dailyDialog?.open)dailyDialog.close();dailyBusy=false;await dailyStart();}else toast('尚未放弃本轮，请稍后重试。');}finally{if(epoch===dailyRequestEpoch)dailyBusy=false;}}
function dailyRestartCancel(){if(dailyTimer?.paused)dailyShowRest();else if(dailyDialog?.open)dailyDialog.close();}
async function dailySubmit(){if(dailyBusy||dailyTimer?.paused||!dailyQuestions||dailyAnswers.length!==dailyQuestions.length)return;dailyBusy=true;const epoch=dailyRequestEpoch,name=document.getElementById('daily-name')?.value||'';dailyCheckpoint();try{const r=await fetch('/api/daily/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,goal:dailyGoalTarget,edition:dailyEdition,attemptId:dailyAttemptId,answers:dailyAnswers})});if(epoch!==dailyRequestEpoch)return;if(!r.ok){toast((await r.text()).slice(0,100));if(r.status===409){const data=await dailyAttemptAction('status');if(data?.paused)dailyShowRest();}return;}const result=await r.json();if(epoch!==dailyRequestEpoch)return;dailyQuestions=null;dailyAnswers=[];dailyTimer=null;dailyAttemptId='';dailyClearCheckpoint();toast(boardSubmitMessage(result));if(location.hash.slice(1).split('?')[0]==='daily')renderDaily();}catch{toast('提交失败，成绩还没上传，请重试。');}finally{if(epoch===dailyRequestEpoch)dailyBusy=false;}}
Object.assign(actions,{'daily-rest':dailyPause,'daily-rest-continue':dailyContinue,'daily-resume':dailyResume,'daily-restart':dailyRestartAsk,'daily-restart-confirm':dailyRestartConfirm,'daily-restart-cancel':dailyRestartCancel});
document.addEventListener('input',event=>{if(event.target.id==='daily-name')dailyCheckpoint();});
window.addEventListener('pagehide',dailyCheckpoint);
setInterval(()=>{document.querySelectorAll('[data-daily-run-clock]').forEach(el=>{el.textContent=runDuration(dailyElapsed());});},1000);

async function bookingSubmit(){const form=document.getElementById('booking-form');if(!form||!form.reportValidity())return;const payload=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type="submit"]');submit.disabled=true;try{const r=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){toast((await r.text()).slice(0,80));submit.disabled=false;return;}toast('预约意向已提交，等待站长确认。');renderMember();}catch{toast('预约暂时提交失败，请稍后重试。');submit.disabled=false;}}

let selectedIndustry='programmer',industryPractice=null,industryChallenge=null;
const INDUSTRY_PREFERENCE='english-quest-selected-industry';
function selectIndustry(id){
 if(!industries.some(sector=>sector.id===id))return false;
 selectedIndustry=id;
 try{localStorage.setItem(INDUSTRY_PREFERENCE,id);}catch{}
 return true;
}
function restoreIndustrySelection(){
 try{const id=localStorage.getItem(INDUSTRY_PREFERENCE);if(industries.some(sector=>sector.id===id))selectedIndustry=id;}catch{}
}
function industryData(){return industries.find(x=>x.id===selectedIndustry)||industries[0];}
function industryWord(sector,id){const base=all.get(String(id)),meaning=sector.glosses?.[id],label=sector.displayWords?.[id];return meaning||label?{...base,word:label||base.word,zh:meaning||base.zh,full:meaning?`${sector.name}常用含义：${meaning}`:base.full}:base;}
function industrySeen(id){const ids=new Set(industries.find(x=>x.id===id)?.wordIds||[]);return (p.industries?.[id]?.seen||[]).filter(word=>ids.has(word));}
function industryWrong(id){const allowed=new Set(industries.find(x=>x.id===id)?.wordIds||[]);return Object.entries(p.industries?.[id]?.answers||{}).filter(([word,answer])=>allowed.has(Number(word))&&answer?.correct===false).map(([word])=>Number(word));}
function industryReviewSummary(){const pending=industries.map(sector=>({sector,count:industryWrong(sector.id).length})).filter(x=>x.count);return pending.length?`<section class="panel" style="margin-top:18px"><h2>专项错词</h2><p class="muted">保留各行业的含义，单独复习；不改主线通关和段位。</p><div class="button-row">${pending.map(({sector,count})=>button(`${esc(sector.name)} · ${count} 个错词`,'industry-review-open','secondary',`data-id="${sector.id}"`)).join('')}</div></section>`:'';}
function industrySkipped(id){const entry=p.industries?.[id];return Object.entries(entry?.skipped||{}).filter(([,at])=>at>(entry?.skipResetAt||0)).map(([word])=>Number(word));}
function markIndustrySkipped(sector,id){p.industries||={};const entry=p.industries[sector]||={seen:[]};entry.skipped||={};entry.skipped[String(id)]=Date.now();save();}
function industryResetSkipped(){const sector=industryData();p.industries||={};const entry=p.industries[sector.id]||={seen:[]};entry.skipResetAt=Date.now();entry.skipped={};save();renderIndustries();}
async function renderIndustries(){
 const sector=industryData();if(!sector)return;const extended=sector.wordIds.length-sector.coreCount,sentenceCount=Object.keys(sector.examples||{}).length;
 app.innerHTML=intro('行业与考试专项，按自己的目标练。','每条路线单独练习、单独上榜；和同方向的学习者比。')+`<section class="panel main-route-card"><div><span class="eyebrow">主线 · 不用选行业</span><h2>继续 ${num(C.goal(p))} 词闯关</h2><p>按关卡从简单到难往前走。行业和考试专项想练再选，不影响主线进度。</p><strong>已通关 ${C.stats(p).passed} 关 · 已练 ${C.stats(p).learned} 词</strong></div>${button('继续主线闯关','map','primary')}</section><section class="panel" id="industry-current" style="margin:20px 0;scroll-margin-top:24px"><h2>${esc(sector.name)} · ${sector.wordIds.length} 个专项词</h2><p class="muted">${sector.category==='exam'?'按参考词池自由练习，每轮 10 词。':`精选 ${sector.coreCount} 词已核对行业含义，可反复练；${extended?`另有 ${extended} 个待审校扩展词，可自愿试练。`:''}${sentenceCount?`${sentenceCount} 词各配两句双语用法，可朗读并练句子选词。`:''}每轮 10 词。`}行业榜只从已核对的精选词出 20 题；考试榜按参考词池出题。答对数优先，同分比用时；可反复挑战，只保留最好成绩。</p><div class="button-row">${button(sector.category==='exam'?'开始自由练习':`练精选 ${sector.coreCount} 词`,'industry-practice','primary')}${sector.category==='industry'&&extended>0?button(`试练扩展 ${extended} 词`,'industry-practice-expand','secondary'):''}${sentenceCount?button(`句子选词 · ${sentenceCount} 词`,'industry-practice-sentences','secondary'):''}${industryWrong(sector.id).length?button(`复习 ${industryWrong(sector.id).length} 个专项错词`,'industry-practice-wrong','secondary'):''}${button('挑战专项榜','industry-challenge','secondary')}${button('反馈词表问题','industry-feedback','ghost')}${industrySkipped(sector.id).length?button('恢复已跳过的词','industry-reset-skipped','ghost'):''}</div><div id="industry-board" class="industry-board"><p class="muted">正在加载专项永久榜…</p></div></section><details class="panel industry-preview"><summary>查找专项词 · ${num(sector.wordIds.length)} 词</summary><label class="industry-search-label" for="industry-search">按英文或中文找词</label><input id="industry-search" class="answer-field" type="search" maxlength="80" placeholder="例如 gene 或 基因" autocomplete="off"><p id="industry-search-status" class="caption" role="status" aria-live="polite"></p><div id="industry-search-results"></div></details><h2>行业专项 · 自选</h2><div class="industry-grid">${industries.filter(x=>x.category!=='exam').map(x=>`<button class="industry-card ${x.id===sector.id?'active':''}" data-action="industry-select" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small><span>已练 ${industrySeen(x.id).length} / ${x.wordIds.length} 词</span></button>`).join('')}</div><h2>学段与考试</h2><div class="industry-grid">${industries.filter(x=>x.category==='exam').map(x=>`<button class="industry-card ${x.id===sector.id?'active':''}" data-action="industry-select" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small><span>已练 ${industrySeen(x.id).length} / ${x.wordIds.length} 词</span></button>`).join('')}</div>`;
 renderIndustryVocabulary();document.getElementById('industry-search')?.addEventListener('input',event=>renderIndustryVocabulary(event.target.value));
 await loadBoardView(createBoardView('industry',sector.id,sector.name+'永久榜'));
}
function renderIndustryVocabulary(query=''){const sector=industryData(),needle=query.trim().toLowerCase(),matches=sector.wordIds.map(id=>industryWord(sector,id)).filter(word=>!needle||word.word.toLowerCase().includes(needle)||word.zh.includes(needle));if(needle){const relevance=word=>word.word.toLowerCase()===needle||word.zh.split(/[；;]/).some(sense=>sense.trim()===needle)?0:word.word.toLowerCase().startsWith(needle)||word.zh.startsWith(needle)?1:word.word.toLowerCase().includes(needle)?2:3;matches.sort((a,b)=>relevance(a)-relevance(b));}const shown=matches.slice(0,30);document.getElementById('industry-search-status').textContent=needle?`找到 ${matches.length} 词${matches.length>30?'，先显示前 30 词；可以写得更具体。':''}`:`共 ${num(sector.wordIds.length)} 词，先显示前 30 词。输入英文或中文可搜索整条路线。`;document.getElementById('industry-search-results').innerHTML=shown.length?shown.map(word=>`<div class="vocab-row industry-vocab-row"><div><strong>${esc(word.word)}</strong><p>${esc(word.zh)}</p></div><div class="industry-vocab-actions">${button('练这个词','industry-practice-word','ghost',`data-id="${word.id}"`)}<button class="sound" data-action="speak-industry-word" data-id="${sector.id}:${word.id}" aria-label="朗读 ${esc(word.word)}">♪</button></div></div>`).join(''):'<p class="muted">这条路线暂时没收录这个词。可以换个关键词，或反馈给站长。</p>';}
function industryPracticeWord(id){const sector=industryData(),word=industryWord(sector,Number(id));if(!word||!sector.wordIds.includes(word.id))return;const scope=sector.examples?.[word.id]?.length===2?'sentences':'core';industryPractice={sector:sector.id,scope,pool:sector.wordIds,items:[word],index:0,correct:0,answered:false,options:[]};renderIndustryPractice();window.scrollTo({top:0});}
function industryPracticeStart(scope='core'){const sector=industryData(),raw=scope==='wrong'?industryWrong(sector.id):sector.category==='industry'?(scope==='extended'?sector.wordIds.slice(sector.coreCount):scope==='sentences'?sector.wordIds.slice(0,sector.coreCount).filter(id=>sector.examples?.[id]?.length===2):sector.wordIds.slice(0,sector.coreCount)):sector.wordIds,skipped=new Set(industrySkipped(sector.id)),pool=raw.filter(id=>!skipped.has(id)),seen=new Set(industrySeen(sector.id)),ids=pool.filter(id=>!seen.has(id));if(!pool.length){toast('这组词都已跳过，可先恢复已跳过的词。');renderIndustries();return;}const selected=(ids.length?ids:pool).slice(0,10);industryPractice={sector:sector.id,scope,pool,items:selected.map(id=>industryWord(sector,id)),index:0,correct:0,answered:false,options:[]};renderIndustryPractice();}
// Do not turn a synonym or alternate spelling into a supposedly wrong cloze answer.
function industryChoicePool(sector,word,pool,cloze){if(!cloze)return pool;const senses=meaning=>String(meaning).split(/[；;]/).map(x=>x.trim()).filter(Boolean),target=new Set(senses(word.zh)),groups=(sector.confusableGroups||[]).filter(group=>group.includes(word.id));return pool.filter(other=>other.id===word.id||(!senses(other.zh).some(sense=>target.has(sense))&&!groups.some(group=>group.includes(other.id))));}
function renderIndustryPractice(){practiceAutoCancel();const state=industryPractice;if(!state)return;const sector=industries.find(x=>x.id===state.sector);if(state.index>=state.items.length){const wrongCount=industryWrong(state.sector).length;app.innerHTML=`<section class="panel result"><div class="result-medal">★</div><h1>${esc(sector.name)}，这轮练完了！</h1><p>答对 ${state.correct} / ${state.items.length}。已练 ${state.pool.filter(id=>industrySeen(sector.id).includes(id)).length} / ${state.pool.length} 个${state.scope==='extended'?'扩展':'专项'}词。${wrongCount?`还有 ${wrongCount} 个专项错词待复习，可从复习营地或专项页回来练。`:'当前没有待复习的专项错词。'}</p><div class="button-row">${button(state.scope==='wrong'&&!wrongCount?'练更多精选词':'继续练下一轮',state.scope==='extended'?'industry-practice-expand':state.scope==='sentences'?'industry-practice-sentences':state.scope==='wrong'&&industryWrong(state.sector).length?'industry-practice-wrong':'industry-practice','primary')}${button('看专项榜','industries','secondary')}</div></section>`;confetti();return;}const word=state.items[state.index],candidate=sector.category==='industry'&&sector.wordIds.indexOf(word.id)>=sector.coreCount,optionIds=sector.glosses?.[word.id]?sector.wordIds.slice(0,sector.coreCount):sector.wordIds,pool=optionIds.map(id=>industryWord(sector,id));const cloze=state.scope==='sentences',example=cloze?sector.examples[word.id][state.index%2]:null;state.options=C.choices(word,industryChoicePool(sector,word,pool,cloze),cloze?'word':'zh');state.answered=false;app.innerHTML=`<div class="exercise question-workspace"><div class="exercise-top">${button('返回专项','industries','ghost')}<span>${esc(sector.name)}自由练习 ${state.index+1} / ${state.items.length}</span><div class="bar"><i style="width:${state.index/state.items.length*100}%"></i></div></div>${renderPracticeMode()}<section class="panel exercise-card question-card"><div class="question-content"><div class="eyebrow">${cloze?'句子选词 · 选择缺少的词':'英 → 中 · 选出意思'}${candidate?" · 扩展词待审校":""}</div><h2 class="question-title ${cloze?'':'large'}">${esc(cloze?example.text.replace(new RegExp('\\b'+escapeRegex(word.word)+'\\b','i'),'_____'):word.word)}</h2>${cloze?`<p class="translation">${esc(example.translation)}</p>`:''}<div class="options">${state.options.map((x,i)=>button(`${i+1}. ${esc(cloze?x.word:x.zh)}`,'industry-practice-answer','option',`data-id="${x.id}"`)).join('')}</div></div><div id="industry-feedback"></div>${sector.category==='industry'?`<div class="exercise-footer" id="industry-controls">${button('跳过这个词','industry-practice-skip','ghost')}${button('反馈并跳过','industry-word-feedback','ghost',`data-id="${word.id}"`)}</div>`:''}</section></div>`;}
function industryPracticeAnswer(id){const state=industryPractice;if(!state||state.answered)return;const word=state.items[state.index],sector=industries.find(x=>x.id===state.sector),correct=Number(id)===word.id;state.answered=true;if(typeof StudyTools!=='undefined'){StudyTools.record({id:'industry-'+state.sector+'-'+word.id,en:word.word,zh:word.zh},'word',{correct,mode:'quest'});if(state.scope==='sentences'){const ex=sector.examples?.[word.id]?.[state.index%2];if(ex)StudyTools.record({id:'industry-ex-'+state.sector+'-'+word.id+'-'+(state.index%2),en:ex.text,zh:ex.translation},'sentence',{correct,mode:'quest'});}}if(correct)state.correct++;p.industries ||= {};p.industries[state.sector] ||= {seen:[]};p.industries[state.sector].answers||={};p.industries[state.sector].answers[word.id]={correct,at:Date.now()};if(!p.industries[state.sector].seen.includes(word.id))p.industries[state.sector].seen.push(word.id);save();const controls=document.getElementById('industry-controls');if(controls)controls.innerHTML='';document.querySelectorAll('.option').forEach(el=>{el.disabled=true;if(Number(el.dataset.id)===word.id)el.classList.add('correct');else if(el.dataset.id===String(id))el.classList.add('wrong');});document.getElementById('industry-feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'答对了。':'答错了。'}</strong><details class="answer-details"><summary>查看释义与例句</summary><p>${esc(word.word)} · ${esc(word.full)}</p>${sector.category==='industry'?(sector.examples?.[word.id]?wordExamples(word,sector.examples[word.id],'speak-industry-example',sector.id+':'):'<p class="caption">这个词的专项例句还在核对；若含义或选词不贴题，请点“反馈此词”。</p>'):wordExamples(word)}</details></div><div class="exercise-footer">${button('听单词','speak-industry-word','ghost',`data-id="${sector.id}:${word.id}"`)}${button('反馈此词','industry-word-feedback','ghost',`data-id="${word.id}"`)}${button('继续','industry-practice-next','primary')}</div>`;const index=state.index;practiceAutoNext(correct,industryPracticeNext,()=>industryPractice===state&&state.index===index&&state.answered);}
function industryPracticeNext(){if(!industryPractice?.answered)return;industryPractice.index++;renderIndustryPractice();}
function industryPracticeSkip(){const state=industryPractice;if(!state||state.answered)return;markIndustrySkipped(state.sector,state.items[state.index].id);state.index++;renderIndustryPractice();}
async function industryChallengeStart(){const sector=industryData();try{const r=await fetch(`/api/industries/challenge?sector=${sector.id}`);if(!r.ok)throw Error();const data=await r.json();industryChallenge={sector:sector.id,name:sector.name,date:data.date,edition:data.edition,attemptId:data.attemptId,questions:data.questions,answers:[],position:0};renderIndustryChallenge();}catch{toast('专项挑战暂时无法开始。');}}
function renderIndustryChallenge(){const state=industryChallenge;if(!state)return;if(state.position>=state.questions.length){app.innerHTML=`<section class="panel exercise-card question-card"><div class="eyebrow">${esc(state.name)} · 专项榜单挑战</div><h2>20 题做完了，提交榜单成绩</h2><p class="muted">可多次挑战，只保留最好成绩。昵称和最佳成绩取得时刻会显示在公开榜单。</p><input id="industry-name" class="answer-field" maxlength="16" placeholder="榜单昵称" aria-label="榜单昵称">${button('提交专项成绩','industry-challenge-submit','primary daily-answer')}</section>`;return;}const q=state.questions[state.position];app.innerHTML=`<div class="exercise question-workspace"><div class="exercise-top">${button('返回专项','industries','ghost')}<span>${esc(state.name)}榜单挑战 ${state.position+1} / 20</span><div class="bar"><i style="width:${state.position*5}%"></i></div></div><section class="panel exercise-card question-card"><div class="eyebrow">英 → 中 · 选出意思</div><h2 class="question-title large">${esc(q.word)}</h2><div class="options">${q.options.map((x,i)=>button(`${i+1}. ${esc(x.zh)}`,'industry-challenge-answer','option',`data-id="${x.id}"`)).join('')}</div></section></div>`;}
function industryChallengeAnswer(id){const state=industryChallenge;if(!state||state.answers.length!==state.position)return;state.answers.push(Number(id));state.position++;renderIndustryChallenge();}
async function industryChallengeSubmit(){const state=industryChallenge;if(!state||state.answers.length!==20)return;const name=document.getElementById('industry-name')?.value||'';try{const r=await fetch('/api/industries/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sector:state.sector,edition:state.edition,attemptId:state.attemptId,name,answers:state.answers})});if(!r.ok){toast((await r.text()).slice(0,100));if(r.status===409){industryChallenge=null;renderIndustries();}return;}const data=await r.json();selectIndustry(state.sector);industryChallenge=null;toast(boardSubmitMessage(data,'专项挑战'));renderIndustries();}catch{toast('提交失败，请重试。');}}

let raceTimer=null,raceCurrent=null,raceViewKey='',raceBusy=false,raceName='';
function racePollStart(){if(!raceTimer)raceTimer=setInterval(()=>{if(location.hash.slice(1).split('?')[0]==='race')raceRefresh();else racePollStop();},1500);}
function racePollStop(){if(raceTimer){clearInterval(raceTimer);raceTimer=null;}raceViewKey='';}
async function renderRace(){app.innerHTML=intro('竞技赛，两个人一起冲线。','选同一词量、竞技段位相同或相差一阶，才会进入同一场对局。')+'<section class="panel">正在读取竞技赛…</section>';await raceRefresh(true);}
async function raceRefresh(force=false){try{const r=await fetch('/api/race/status');if(!r.ok)throw Error();const state=await r.json();if(location.hash.slice(1).split('?')[0]!=='race')return;raceCurrent=state;raceDisplay(state,force);}catch{if(location.hash.slice(1).split('?')[0]==='race')app.innerHTML='<section class="panel empty"><h2>竞技赛暂时没连上。</h2><p>主线和行业专项仍可继续。</p></section>';}}
function raceNotices(notices){return `<section class="panel"><h2>系统战报</h2>${notices.length?`<div class="race-notices">${notices.slice(0,10).map(x=>`<p>🏁 <strong>${esc(x.winner)}</strong> 率先完成 ${num(x.goal)} 词竞技赛，用时 ${Math.floor(x.seconds/60)} 分 ${x.seconds%60} 秒</p>`).join('')}</div>`:'<p class="muted">还没有完赛战报。第一位冲线的玩家会出现在这里。</p>'}</section>`;}
function raceDisplay(state,force=false){if(typeof GameEffects!=='undefined')GameEffects.mark('race',state);const me=state.me||{},opponent=state.opponent||{},key=[state.mode,state.goal,me.progress,me.errors,opponent.progress,opponent.errors,state.winner,state.profile.points,state.notices?.[0]?.at,state.roomId].join(':');if(!force&&key===raceViewKey)return;raceViewKey=key;const stats=C.stats(p),baseDone=stats.passed===C.goal(p)/10,base=baseDone?C.rank(stats.wrongUnique,C.goal(p)).name:'待结算',rank=`${esc(state.profile.tier)} · ${state.profile.points} 分 · ${state.profile.wins} 胜 ${state.profile.losses} 负`;let content='';
 if(state.mode==='idle'){racePollStop();content=`<div class="profile-grid"><section class="panel"><h2>开始匹配</h2><p>基础闯关段位：${esc(base)}<br>竞技段位：${rank}</p><label class="race-field">榜单昵称<input id="race-name" maxlength="16" placeholder="你的昵称" value="${esc(raceName)}"></label><label class="race-field">本局词量<select id="race-goal">${state.goals.map(n=>`<option value="${n}">${num(n)} 词</option>`).join('')}</select></label><p class="caption">每词一题，答错要重答。100 词适合快速试玩；3,000 词以上可能耗时数小时，进度会保存在本站，可返回继续。</p>${button('开始匹配','race-join','primary')}<div class="backup"><h3>密码房 · 邀请朋友对战</h3><label class="race-field">房间密码<input id="race-room-password" type="password" minlength="4" maxlength="32" placeholder="设置 4–32 位密码"></label>${button('创建密码房','race-room-create','secondary')}<label class="race-field">好友房号<input id="race-room-code" placeholder="输入房号"></label><label class="race-field">好友密码<input id="race-room-join-password" type="password" placeholder="输入房间密码"></label>${button('加入好友房间','race-room-join','ghost')}</div></section>${raceNotices(state.notices)}</div>`;}
 else if(state.mode==='waiting'){racePollStart();content=`<section class="panel race-wait">${typeof GameEffects!=='undefined'?GameEffects.waiting('正在匹配真实对手'):'<div class="result-medal">⌛</div>'}<h2>${state.roomId?'等待好友进入密码房':'正在匹配 '+num(state.goal)+' 词对手'}</h2>${state.roomId?`<div class="duo-invite"><strong>${esc(state.roomId)}</strong>${button('复制房号','race-room-copy','secondary')}${button('复制邀请链接','race-room-link','ghost')}</div>`:''}<p>竞技段位 ${rank}。双方选择相同词量、段位最多相差一阶才会开赛。保持页面打开，匹配成功会自动进入题目。</p>${button('取消匹配','race-cancel','ghost')}</section>${raceNotices(state.notices)}`;}
 else if(state.mode==='racing'){racePollStart();const q=state.question;content=`<div class="race-scoreboard"><div><strong>${esc(me.name)} · 你</strong><span>${num(me.progress)} / ${num(state.goal)} 词 · 错 ${me.errors}</span><div class="bar"><i style="width:${me.progress/state.goal*100}%"></i></div></div><b>VS</b><div><strong>${esc(opponent.name)}</strong><span>${num(opponent.progress)} / ${num(state.goal)} 词 · 错 ${opponent.errors}</span><div class="bar"><i style="width:${opponent.progress/state.goal*100}%"></i></div></div></div><section class="panel exercise-card race-question"><div class="eyebrow">${num(state.goal)} 词竞技赛 · 第 ${num(me.progress+1)} 题</div><h2 class="question-title large">${esc(q.word)}</h2><div class="options">${q.options.map((x,i)=>button(`${i+1}. ${esc(x.zh)}`,'race-answer','option',`data-id="${x.id}"`)).join('')}</div><p id="race-feedback" class="caption"></p></section><p class="caption">先答完所选词量的玩家获胜。退出对局视为认输。${button('退出并认输','race-forfeit','ghost')}</p>`;}
 else {racePollStop();content=`<section class="panel result"><div class="result-medal">${state.won?'★':'↻'}</div><h1>${state.won?'你赢了！':'这局结束了。'}</h1><p>${state.reason==='completed'?'有人率先刷完全部题目，完赛战报已更新。':'本局因一方退出而结束。'}</p><div class="result-metrics"><div><strong>${num(me.progress)}</strong><small>你完成的词</small></div><div><strong>${num(opponent.progress)}</strong><small>对手完成的词</small></div><div><strong>${state.profile.points}</strong><small>竞技积分 · ${esc(state.profile.tier)}</small></div></div>${button('再匹配一局','race-again','primary')}</section>${raceNotices(state.notices)}`;}
 app.innerHTML=state.mode==='racing'?`<div class="live-question-workspace">${intro('竞技赛，两个人一起冲线。','基础段位看主线错词，竞技段位看对战胜负；匹配只跨一阶。')}${typeof GameEffects!=='undefined'?GameEffects.controls():''}${content}</div>`:intro('竞技赛，两个人一起冲线。','基础段位看主线错词，竞技段位看对战胜负；匹配只跨一阶。')+(typeof GameEffects!=='undefined'?GameEffects.controls():'')+content;const invited=new URLSearchParams(location.hash.split('?')[1]||'').get('room');const field=document.getElementById('race-room-code');if(field&&invited)field.value=invited;}
async function raceJoin(){const goal=Number(document.getElementById('race-goal')?.value||raceCurrent?.goal||100),name=document.getElementById('race-name')?.value||raceName||'英语旅人';raceName=name;try{const r=await fetch('/api/race/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal,name})});if(!r.ok){toast((await r.text()).slice(0,80));return;}const data=await r.json();raceCurrent=data;raceDisplay(data,true);}catch{toast('匹配暂时失败，请重试。');}}
async function raceRoomPost(action,payload){try{const r=await fetch('/api/race/room/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){toast((await r.text()).slice(0,80));return;}const data=await r.json();raceCurrent=data;raceDisplay(data,true);}catch{toast('密码房暂时不可用，请重试。');}}
function raceRoomCreate(){const goal=Number(document.getElementById('race-goal')?.value||100),name=document.getElementById('race-name')?.value||'英语旅人',password=document.getElementById('race-room-password')?.value||'';raceName=name;raceRoomPost('create',{goal,name,password});}
function raceRoomJoin(){const code=document.getElementById('race-room-code')?.value||'',name=document.getElementById('race-name')?.value||'英语旅人',password=document.getElementById('race-room-join-password')?.value||'';raceName=name;raceRoomPost('join',{code,name,password});}
async function raceRoomCopy(){try{await navigator.clipboard.writeText(raceCurrent.roomId);toast('房号已复制。请另行告诉好友密码。');}catch{toast('复制失败，请手动选中房号。');}}
async function raceRoomLink(){try{await navigator.clipboard.writeText(location.origin+'/#race?room='+encodeURIComponent(raceCurrent.roomId));toast('邀请链接已复制，密码请单独告诉好友。');}catch{toast('复制失败，请手动分享房号。');}}
async function raceAnswer(id){const state=raceCurrent;if(!state||state.mode!=='racing'||raceBusy)return;raceBusy=true;try{const r=await fetch('/api/race/answer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matchId:state.matchId,index:state.me.progress,choice:Number(id)})});if(!r.ok){toast((await r.text()).slice(0,80));raceBusy=false;raceRefresh(true);return;}const data=await r.json();raceCurrent=data.state;raceDisplay(data.state,true);if(typeof GameEffects!=='undefined'&&data.state.mode==='racing')GameEffects.answer(data.correct,'race',[state.matchId,state.me.progress,data.state.me?.errors].join(':'));if(!data.correct){const note=document.getElementById('race-feedback');if(note)note.textContent='这题再试一次，答对才会前进。';}}catch{toast('提交答案失败，请重试。');}raceBusy=false;}
async function raceCancel(){try{await fetch('/api/race/cancel',{method:'POST'});raceRefresh(true);}catch{toast('取消失败，请重试。');}}
async function raceForfeit(){if(!confirm('确定退出对局吗？这局会计为失利。'))return;try{const r=await fetch('/api/race/forfeit',{method:'POST'});if(!r.ok)throw Error();raceRefresh(true);}catch{toast('退出失败，请重试。');}}
function raceAgain(){const goal=raceCurrent?.goal||100;racePollStop();raceCurrent={mode:'idle',profile:raceCurrent.profile,goals:[100,500,1000,3000,5000,10000,20000],notices:raceCurrent.notices};raceDisplay(raceCurrent,true);const select=document.getElementById('race-goal');if(select)select.value=String(goal);}

let duoTimer=null,duoCurrent=null,duoViewKey='',duoBusy=false;
function duoPollStart(){if(!duoTimer)duoTimer=setInterval(()=>{if(location.hash.slice(1).split('?')[0]==='duo')duoRefresh();else duoPollStop();},1500);}
function duoPollStop(){if(duoTimer){clearInterval(duoTimer);duoTimer=null;}duoViewKey='';}
async function duoRefresh(force=false){try{const r=await fetch('/api/duo/status');if(!r.ok)throw Error();const state=await r.json();if(location.hash.slice(1).split('?')[0]!=='duo')return;duoCurrent=state;duoDisplay(state,force);}catch{if(location.hash.slice(1).split('?')[0]==='duo')app.innerHTML='<section class="panel empty"><h2>双排暂时没连上。</h2></section>';}}
async function renderDuo(){app.innerHTML=intro('双排，两个人一起上榜。','邀请一位搭档，共享刷题进度；也能组队打 2 对 2 竞技赛。')+'<section class="panel">正在读取队伍…</section>';await duoRefresh(true);}
function duoBoards(state){const boards=state.boards||{practice:[],competitive:[]};return `<div class="profile-grid"><section class="panel"><h2>协作刷题榜</h2>${boards.practice.length?boards.practice.slice(0,10).map((x,i)=>`<div class="daily-row"><b>${i+1}</b><span>${esc(x.name)}</span><strong>${num(x.practiceTotal)} 词</strong></div>`).join(''):'<p class="muted">还没有完整队伍。</p>'}</section><section class="panel"><h2>双排竞技榜</h2>${boards.competitive.length?boards.competitive.slice(0,10).map((x,i)=>`<div class="daily-row"><b>${i+1}</b><span>${esc(x.name)}</span><strong>${esc(x.tier)}</strong><small>${x.points} 分</small></div>`).join(''):'<p class="muted">还没有完整队伍。</p>'}</section></div>`;}
function duoNotices(items){return `<section class="panel"><h2>双排战报</h2>${items.length?items.slice(0,8).map(x=>`<p class="duo-notice">🏁 ${esc(x.team)} 率先完成 ${num(x.goal)} 词，用时 ${Math.floor(x.seconds/60)} 分 ${x.seconds%60} 秒</p>`).join(''):'<p class="muted">第一支冲线的双人队伍会出现在这里。</p>'}</section>`;}
function duoControls(state){return `<label class="race-field">本轮词量<select id="duo-goal">${state.goals.map(n=>`<option value="${n}">${num(n)} 词</option>`).join('')}</select></label><div class="button-row">${button('开始协作刷题','duo-practice-start','primary')}${button('匹配 2 对 2','duo-race-join','secondary')}</div><div class="backup"><h3>2 对 2 密码房</h3><label class="race-field">房间密码<input id="duo-room-password" type="password" minlength="4" maxlength="32" placeholder="设置 4–32 位密码"></label>${button('创建竞技密码房','duo-room-create','secondary')}<label class="race-field">对方房号<input id="duo-room-code" placeholder="输入另一队房号"></label><label class="race-field">对方密码<input id="duo-room-join-password" type="password" placeholder="输入房间密码"></label>${button('加入竞技密码房','duo-room-join','ghost')}</div><p class="caption">两人共用一道当前题，谁先答对，队伍就前进一词；同时提交过期题会提示刷新。大词量对局可能耗时数小时。</p>`;}
function duoDisplay(state,force=false){if(typeof GameEffects!=='undefined')GameEffects.mark('duo',state);const team=state.team||{},key=[state.mode,team.names,team.practiceTotal,team.practiceProgress,team.practiceErrors,state.myProgress,state.opponentProgress,state.won,state.notices?.[0]?.at,state.boards?.competitive?.[0]?.points,state.roomId].join(':');if(!force&&key===duoViewKey)return;duoViewKey=key;let content='';
 if(state.mode==='solo'){duoPollStop();content=`<div class="profile-grid"><section class="panel"><h2>发起双排</h2><p class="muted">创建队伍后，把邀请口令发给搭档。对方加入后，双方会看到同一份进度与排名。</p><label class="race-field">你的昵称<input id="duo-create-name" maxlength="16" placeholder="你的昵称"></label><label class="race-field">组队密码（可选）<input id="duo-create-password" type="password" minlength="4" maxlength="32" placeholder="设置后需凭密码加入"></label>${button('生成搭档口令','duo-create','primary')}</section><section class="panel"><h2>加入搭档</h2><label class="race-field">邀请口令<input id="duo-join-code" placeholder="输入搭档发来的口令"></label><label class="race-field">你的昵称<input id="duo-join-name" maxlength="16" placeholder="你的昵称"></label><label class="race-field">组队密码<input id="duo-join-password" type="password" placeholder="有密码时填写"></label>${button('加入队伍','duo-join','secondary')}</section></div>${duoBoards(state)}${duoNotices(state.notices)}`;}
 else if(state.mode==='inviting'){duoPollStart();content=`<section class="panel race-wait">${typeof GameEffects!=='undefined'?GameEffects.waiting('等待搭档加入'):''}<h2>等待搭档加入</h2><p>队伍由 ${esc(team.names)} 创建。把下面的口令发给搭档，对方在“双排”页输入即可加入。</p><div class="duo-invite"><strong>${esc(team.inviteCode)}</strong>${button('复制口令','duo-copy','secondary')}${button('复制组队链接','duo-team-link','ghost')}</div><p class="caption">${team.hasPassword?'这个队伍设了密码，请单独告诉搭档。':'对方加入后页面会自动更新。'} 口令只用于加入队伍。</p>${button('取消组队','duo-leave','ghost')}</section>${duoBoards(state)}`;}
 else if(state.mode==='ready'||state.mode==='practice_done'){duoPollStop();content=`<section class="panel"><h2>${esc(team.names)} · 双排搭档</h2><p>协作累计 ${num(team.practiceTotal)} 词 · 双排竞技 ${esc(team.tier)} ${team.points} 分 · ${team.wins} 胜 ${team.losses} 负</p>${state.mode==='practice_done'?'<div class="notice">这轮协作刷题完成啦！两个人的总进度已经更新。</div>':''}${duoControls(state)}<div class="backup">${button('解除双排关系','duo-leave','ghost')}</div></section>${duoBoards(state)}${duoNotices(state.notices)}`;}
 else if(state.mode==='practicing'){duoPollStart();content=`<div class="race-scoreboard"><div><strong>${esc(team.names)}</strong><span>协作 ${num(team.practiceProgress)} / ${num(team.practiceGoal)} 词 · 错 ${team.practiceErrors}</span><div class="bar"><i style="width:${team.practiceProgress/team.practiceGoal*100}%"></i></div></div><b>🤝</b><div><strong>共享记录</strong><span>累计练过 ${num(team.practiceTotal)} 词</span></div></div><section class="panel exercise-card race-question"><div class="eyebrow">双排协作 · 第 ${num(team.practiceProgress+1)} 题</div><h2 class="question-title large">${esc(state.question.word)}</h2><div class="options">${state.question.options.map((x,i)=>button(`${i+1}. ${esc(x.zh)}`,'duo-practice-answer','option',`data-id="${x.id}"`)).join('')}</div><p id="duo-feedback" class="caption"></p></section><div class="button-row" style="margin-top:18px">${button('结束本轮练习','duo-practice-stop','ghost')}</div>`;}
 else if(state.mode==='waiting'){duoPollStart();content=`<section class="panel race-wait">${typeof GameEffects!=='undefined'?GameEffects.waiting('正在匹配真实对手'):'<div class="result-medal">⌛</div>'}<h2>${esc(team.names)} ${state.roomId?'等待另一支队伍加入':'正在匹配另一支队伍'}</h2>${state.roomId?`<div class="duo-invite"><strong>${esc(state.roomId)}</strong>${button('复制房号','duo-room-copy','secondary')}${button('复制邀请链接','duo-room-link','ghost')}</div>`:''}<p>${num(state.goal)} 词双排竞技 · ${esc(team.tier)}段位。双方队伍段位最多相差一阶。</p>${button('取消匹配','duo-race-cancel','ghost')}</section>${duoBoards(state)}`;}
 else if(state.mode==='racing'){duoPollStart();content=`<div class="race-scoreboard"><div><strong>${esc(team.names)} · 我方</strong><span>${num(state.myProgress)} / ${num(state.goal)} 词 · 错 ${state.myErrors}</span><div class="bar"><i style="width:${state.myProgress/state.goal*100}%"></i></div></div><b>VS</b><div><strong>${esc(state.opponentName)}</strong><span>${num(state.opponentProgress)} / ${num(state.goal)} 词 · 错 ${state.opponentErrors}</span><div class="bar"><i style="width:${state.opponentProgress/state.goal*100}%"></i></div></div></div><section class="panel exercise-card race-question"><div class="eyebrow">双排竞技 · 第 ${num(state.myProgress+1)} 题</div><h2 class="question-title large">${esc(state.question.word)}</h2><div class="options">${state.question.options.map((x,i)=>button(`${i+1}. ${esc(x.zh)}`,'duo-race-answer','option',`data-id="${x.id}"`)).join('')}</div><p id="duo-feedback" class="caption"></p></section><div class="button-row" style="margin-top:18px">${button('认输并退出','duo-race-forfeit','ghost')}</div>`;}
 else {duoPollStop();content=`<section class="panel result"><div class="result-medal">${state.won?'★':'↻'}</div><h1>${state.won?'双排胜利！':'这局双排结束了。'}</h1><p>${state.reason==='completed'?'先完成整场词量的队伍获胜，并进入战报。':'一支队伍选择退出，对局已结束。'}</p><div class="result-metrics"><div><strong>${num(state.myProgress)}</strong><small>我方完成</small></div><div><strong>${num(state.opponentProgress)}</strong><small>对方完成</small></div><div><strong>${team.points}</strong><small>双排竞技积分</small></div></div>${button('返回双排大厅','duo-return','primary')}</section>${duoNotices(state.notices)}`;}
 app.innerHTML=['racing','practicing'].includes(state.mode)?`<div class="live-question-workspace">${intro('双排，两个人一起上榜。','协作进度和双排竞技段位归这支队伍，解除组队后新队伍从头计算。')}${typeof GameEffects!=='undefined'?GameEffects.controls():''}${content}</div>`:intro('双排，两个人一起上榜。','协作进度和双排竞技段位归这支队伍，解除组队后新队伍从头计算。')+(typeof GameEffects!=='undefined'?GameEffects.controls():'')+content;const params=new URLSearchParams(location.hash.split('?')[1]||'');const teamField=document.getElementById('duo-join-code'),roomField=document.getElementById('duo-room-code');if(teamField&&params.get('team'))teamField.value=params.get('team');if(roomField&&params.get('room'))roomField.value=params.get('room');}
async function duoPost(path,payload){const r=await fetch('/api/duo/'+path,{method:'POST',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined});if(!r.ok)throw Error((await r.text()).slice(0,80));const state=await r.json();duoCurrent=state;duoDisplay(state,true);return state;}
async function duoCreate(){try{await duoPost('create',{name:document.getElementById('duo-create-name')?.value||'英语旅人',password:document.getElementById('duo-create-password')?.value||''});}catch(e){toast(e.message||'创建失败');}}
async function duoJoin(){try{await duoPost('join',{code:document.getElementById('duo-join-code')?.value||'',name:document.getElementById('duo-join-name')?.value||'英语旅人',password:document.getElementById('duo-join-password')?.value||''});}catch(e){toast(e.message||'加入失败');}}
async function duoLeave(){if(!confirm('解除组队后，这支队伍的共享进度和双排段位不会带到新队伍。确定解除吗？'))return;try{await duoPost('leave');}catch(e){toast(e.message||'解除失败');}}
async function duoPracticeStart(){try{await duoPost('practice/start',{goal:Number(document.getElementById('duo-goal')?.value||100)});}catch(e){toast(e.message||'开始失败');}}
async function duoPracticeStop(){try{await duoPost('practice/stop');}catch(e){toast(e.message||'结束失败');}}
async function duoRaceJoin(){try{await duoPost('race/join',{goal:Number(document.getElementById('duo-goal')?.value||100)});}catch(e){toast(e.message||'匹配失败');}}
async function duoRoomCreate(){try{await duoPost('race/room/create',{goal:Number(document.getElementById('duo-goal')?.value||100),password:document.getElementById('duo-room-password')?.value||''});}catch(e){toast(e.message||'创建密码房失败');}}
async function duoRoomJoin(){try{await duoPost('race/room/join',{code:document.getElementById('duo-room-code')?.value||'',password:document.getElementById('duo-room-join-password')?.value||''});}catch(e){toast(e.message||'加入密码房失败');}}
async function duoRoomCopy(){try{await navigator.clipboard.writeText(duoCurrent.roomId);toast('房号已复制。请另行告诉对手密码。');}catch{toast('复制失败，请手动选中房号。');}}
async function duoRoomLink(){try{await navigator.clipboard.writeText(location.origin+'/#duo?room='+encodeURIComponent(duoCurrent.roomId));toast('邀请链接已复制，密码请单独告诉对方队伍。');}catch{toast('复制失败，请手动分享房号。');}}
async function duoTeamLink(){try{await navigator.clipboard.writeText(location.origin+'/#duo?team='+encodeURIComponent(duoCurrent.team.inviteCode));toast('组队链接已复制，组队密码请单独告诉搭档。');}catch{toast('复制失败，请手动分享口令。');}}
async function duoAnswer(id,competitive){const state=duoCurrent;if(!state||duoBusy)return;duoBusy=true;try{const body=competitive?{matchId:state.matchId,index:state.myProgress,choice:Number(id)}:{index:state.team.practiceProgress,choice:Number(id)};const r=await fetch('/api/duo/'+(competitive?'race/answer':'practice/answer'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){toast((await r.text()).slice(0,80));duoBusy=false;duoRefresh(true);return;}const data=await r.json();duoCurrent=data.state;duoDisplay(data.state,true);if(typeof GameEffects!=='undefined'&&['racing','practicing'].includes(data.state.mode))GameEffects.answer(data.correct,'duo',[state.matchId||state.team?.id,competitive?state.myProgress:state.team.practiceProgress,competitive?data.state.myErrors:data.state.team?.practiceErrors].join(':'));if(!data.correct){const el=document.getElementById('duo-feedback');if(el)el.textContent='这题再试一次，答对才会前进。';}}catch{toast('答题提交失败，请重试。');}duoBusy=false;}
async function duoRaceCancel(){try{await duoPost('race/cancel');}catch(e){toast(e.message||'取消失败');}}
async function duoRaceForfeit(){if(!confirm('确定认输吗？整个队伍会计为失利。'))return;try{await duoPost('race/forfeit');}catch(e){toast(e.message||'退出失败');}}
async function duoReturn(){duoPollStop();await duoPost('practice/stop');}
async function duoCopy(){try{await navigator.clipboard.writeText(duoCurrent.team.inviteCode);toast('搭档口令已复制。');}catch{toast('复制失败，请手动选中口令。');}}

let friendTimer=null,friendCurrent=null,friendViewKey='';
function friendPollStop(){if(friendTimer){clearInterval(friendTimer);friendTimer=null;}friendViewKey='';}
function friendPayload(activity='idle'){const s=C.stats(p),goal=C.goal(p),complete=s.passed===goal/10;return {name:p.friendName||'英语旅人',goal,baseTier:complete?C.rank(s.wrongUnique,goal).name:'待结算',learned:s.learned,passed:s.passed,activity};}
async function friendSync(activity='idle'){if(!p.friendName)return;const r=await fetch('/api/friends/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(friendPayload(activity))});if(!r.ok)throw Error();return r.json();}
async function renderFriends(){if(!p.friendName){p.friendName='英语旅人';save();}app.innerHTML=intro('好友，一起看见彼此的进度。','先交换口令，再确认好友申请。')+'<section class="panel">正在读取好友…</section>';try{const data=await friendSync('idle');if(location.hash.slice(1)!=='friends')return;friendCurrent=data;friendDisplay(data,true);if(!friendTimer)friendTimer=setInterval(()=>{if(location.hash.slice(1)==='friends')friendRefresh();else friendPollStop();},12000);}catch{app.innerHTML='<section class="panel empty"><h2>好友状态暂时无法读取。</h2></section>';}}
async function friendRefresh(force=false){try{const r=await fetch('/api/friends/status');if(!r.ok)throw Error();const data=await r.json();if(location.hash.slice(1)!=='friends')return;friendCurrent=data;friendDisplay(data,force);}catch{}}
function friendDisplay(data,force=false){const key=JSON.stringify(data);if(!force&&key===friendViewKey)return;friendViewKey=key;const me=data.me;app.innerHTML=intro('好友，一起看见彼此的进度。','好友能看到闯关段位、单排与双排段位，以及当前游戏状态。')+`<div class="profile-grid"><section class="panel"><h2>我的好友资料</h2><label class="race-field">好友昵称<input id="friend-name" maxlength="16" value="${esc(me.name)}"></label>${button('保存昵称','friend-save-name','secondary')}<p style="margin-top:18px">我的好友口令</p><div class="duo-invite"><strong>${esc(me.code)}</strong>${button('复制口令','friend-copy','ghost')}</div><p class="caption">把口令发给想加的人。对方申请后，需要你确认才会互相展示资料。</p><p class="muted">基础段位：${esc(me.baseTier)} · ${num(me.learned)} / ${num(me.goal)} 词<br>单排：${esc(me.soloTier)} ${me.soloPoints} 分 · 双排：${esc(me.duoTier)} ${me.duoPoints} 分</p></section><section class="panel"><h2>添加好友</h2><label class="race-field">对方的好友口令<input id="friend-add-code" placeholder="输入对方发来的口令"></label>${button('发送好友申请','friend-request','primary')}<h3 style="margin-top:25px">收到的申请</h3>${data.incoming.length?data.incoming.map(x=>`<div class="friend-request"><strong>${esc(x.name)}</strong>${button('同意','friend-accept','secondary',`data-id="${esc(x.id)}"`)}${button('拒绝','friend-decline','ghost',`data-id="${esc(x.id)}"`)}</div>`).join(''):'<p class="muted">暂时没有新申请。</p>'}<h3>已发申请</h3>${data.outgoing.length?data.outgoing.map(x=>`<p class="muted">等待 ${esc(x.name)} 确认</p>`).join(''):'<p class="muted">暂无。</p>'}</section></div><section class="panel" style="margin-top:18px"><h2>我的好友 · ${data.friends.length}</h2>${data.friends.length?`<div class="friend-grid">${data.friends.map(x=>`<article class="friend-card"><div class="friend-card-head"><strong>${esc(x.name)}</strong><span>${esc(x.status)}</span></div><p>基础：${esc(x.baseTier)} · ${num(x.learned)} / ${num(x.goal)} 词 · ${num(x.passed)} 关</p><p>单排：${esc(x.soloTier)} ${x.soloPoints} 分<br>双排：${esc(x.duoTier)} ${x.duoPoints} 分</p><small>最近同步：${x.updated?new Date(x.updated*1000).toLocaleString('zh-CN'):'尚未同步'}</small><div>${button('解除好友','friend-remove','ghost',`data-id="${esc(x.code)}"`)}</div></article>`).join('')}</div>`:'<p class="muted">还没有好友。把口令发给想一起学习的人吧。</p>'}</section><p class="caption">学习进度来自好友最近一次同步；当前对局与匹配状态由服务器更新。微信联系方式不会显示在好友资料中。</p>`;}
async function friendPost(path,payload){const r=await fetch('/api/friends/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error((await r.text()).slice(0,80));const data=await r.json();friendCurrent=data;friendDisplay(data,true);}
async function friendSaveName(){p.friendName=(document.getElementById('friend-name')?.value||'英语旅人').trim().slice(0,16)||'英语旅人';save();try{const data=await friendSync();friendCurrent=data;friendDisplay(data,true);toast('昵称已保存。');}catch{toast('保存失败，请重试。');}}
async function friendRequest(){try{await friendPost('request',{code:document.getElementById('friend-add-code')?.value||''});toast('好友申请已发送。');}catch(e){toast(e.message||'发送失败');}}
async function friendAccept(id){try{await friendPost('accept',{id});toast('已经成为好友。');}catch(e){toast(e.message||'操作失败');}}
async function friendDecline(id){try{await friendPost('decline',{id});}catch(e){toast(e.message||'操作失败');}}
async function friendRemove(code){if(!confirm('确定解除好友吗？双方将不再看到彼此资料。'))return;try{await friendPost('remove',{code});toast('好友关系已解除。');}catch(e){toast(e.message||'解除失败');}}
async function friendCopy(){try{await navigator.clipboard.writeText(friendCurrent.me.code);toast('好友口令已复制。');}catch{toast('复制失败，请手动选中口令。');}}

// Industry audio reads the reviewed sentence, independently of main-word examples.
actions['industry-practice-word']=industryPracticeWord;
actions['industry-practice-sentences']=()=>industryPracticeStart('sentences');
actions['speak-industry-example']=id=>{const [sectorId,wordId,index]=String(id).split(':'),text=industries.find(x=>x.id===sectorId)?.examples?.[wordId]?.[Number(index)]?.text;if(text)say(text);};
actions['industry-practice-wrong']=()=>industryPracticeStart('wrong');
actions['industry-review-open']=id=>{if(selectIndustry(id))go('industries');};

actions['speak-industry-word']=id=>{const [sectorId,wordId]=String(id).split(':'),sector=industries.find(x=>x.id===sectorId),word=sector&&industryWord(sector,Number(wordId));if(word)say(word.word);};
